export function createContextualTutorial({storage,requestLocation,onChange=()=>{},onFinish=()=>{}}={}){
 let seen=new Set(),enabled=true,area=null,index=0,busy=false,status='',remembered=true;
 try{const saved=JSON.parse(storage?.getItem(TUTORIAL_KEY)??'null');if(saved?.version===1){enabled=saved.enabled!==false;seen=new Set((Array.isArray(saved.seen)?saved.seen:[]).filter(id=>Object.hasOwn(TUTORIAL_AREAS,id)));}}catch{}
 function persist(){try{if(!storage?.setItem)throw Error();storage.setItem(TUTORIAL_KEY,JSON.stringify({version:1,enabled,seen:[...seen]}));remembered=true;}catch{remembered=false;}}
 const state=()=>({area,index,busy,status,enabled,remembered,page:area?TUTORIAL_AREAS[area]:null,tip:area?TUTORIAL_AREAS[area].tips[index]:null});
 const emit=()=>onChange(state());
 function finish(notify=true){if(!area||busy)return;const completed=area;seen.add(completed);persist();area=null;status='';emit();if(notify)onFinish(completed);}
 return {state,isSeen:id=>seen.has(id),
  visit(id,{force=false}={}){if(area||!Object.hasOwn(TUTORIAL_AREAS,id)||!force&&(!enabled||seen.has(id)))return false;area=id;index=0;busy=false;status='';emit();return true;},
  next(){if(!area||busy)return;if(index+1<TUTORIAL_AREAS[area].tips.length){index++;emit();}else finish();},
  back(){if(area&&!busy&&index>0){index--;emit();}},dismiss:()=>finish(),
  canClose(){if(busy)return false;finish(false);return true;},
  reset(){area=null;busy=false;status='';},resetSeen(){seen.clear();enabled=true;persist();emit();},
  setEnabled(value){enabled=!!value;persist();emit();},
  async allowLocation(){if(area!=='location'||busy)return;busy=true;status='Opening location access…';emit();try{const result=await requestLocation();if(result?.state==='granted'){busy=false;finish();return;}status=result?.state==='denied'?'Location was not allowed. You can continue and change it later in Android Settings → Apps → Nth FootPrints → Permissions → Location.':'Location is unavailable here. You can still search a town or choose a map point.';}catch(error){status=error?.message||'Location access could not open. You can continue without it.';}finally{busy=false;emit();}}
 };
}
export function createTutorialUI({document,window=globalThis.window,storage,requestLocation,show,close,currentArea,canShow=()=>true,icon=()=>'',onStatus=()=>{}}){
 const $=id=>document.getElementById(id);let timer=null,startupPending=false,anchor=null;
 const visible=e=>!!e&&e.getClientRects().length>0&&!e.closest('[hidden]')&&window.getComputedStyle(e).visibility!=='hidden';
 function target(selector){return [...document.querySelectorAll(selector)].map(e=>e.matches('input[type=file],input[type=checkbox]')?e.closest('label')??e:e).filter(visible).sort((a,b)=>Number(!!b.closest('dialog[open]'))-Number(!!a.closest('dialog[open]')))[0]??null;}
 function position(scroll=false){
  const s=controller.state();if(!s.area)return;anchor=target(s.tip.target);if(anchor&&scroll)anchor.scrollIntoView({block:'center',inline:'nearest',behavior:'instant'});
  const card=$('tutorial-card'),spot=$('tutorial-spot'),w=window.innerWidth,h=window.innerHeight,gap=14,css=window.getComputedStyle(document.documentElement),inset=side=>Math.max(14,(parseFloat(css.getPropertyValue('--app-safe-'+side))||0)+10),safeTop=inset('top'),safeBottom=inset('bottom'),safeLeft=inset('left'),safeRight=inset('right'),rect=anchor?.getBoundingClientRect();
  card.style.maxHeight=`${Math.max(100,h-safeTop-safeBottom)}px`;card.style.maxWidth=`${Math.max(100,w-safeLeft-safeRight)}px`;const cw=card.getBoundingClientRect().width,ch=card.getBoundingClientRect().height;
  let left=(w-cw)/2,top=Math.max(safeTop,h-ch-safeBottom);
  if(rect){spot.hidden=false;Object.assign(spot.style,{left:`${Math.max(2,rect.left-5)}px`,top:`${Math.max(2,rect.top-5)}px`,width:`${Math.min(w-4,rect.width+10)}px`,height:`${Math.max(0,Math.min(h-4,rect.bottom+5)-Math.max(2,rect.top-5))}px`});if(w-rect.right>=cw+gap+safeRight){left=rect.right+gap;top=rect.top;}else if(rect.left>=cw+gap+safeLeft){left=rect.left-cw-gap;top=rect.top;}else if(h-rect.bottom>=ch+gap+safeBottom)top=rect.bottom+gap;else if(rect.top>=ch+gap+safeTop)top=rect.top-ch-gap;}else spot.hidden=true;
  left=Math.max(safeLeft,Math.min(w-cw-safeRight,left));top=Math.max(safeTop,Math.min(h-ch-safeBottom,top));Object.assign(card.style,{left:`${left}px`,top:`${top}px`});
 }

 function render(s){$('show-context-tips').checked=s.enabled;if(!s.area)return;const location=s.area==='location';$('tutorial-area').textContent=s.page.label;$('tutorial-count').textContent=s.page.tips.length>1?`${s.index+1} of ${s.page.tips.length}`:'First visit';$('tutorial-icon').innerHTML=icon(s.page.icon);$('tutorial-title').textContent=s.tip.title;$('tutorial-copy').textContent=s.tip.text;$('tutorial-status').textContent=s.status;$('tutorial-remember').textContent=s.remembered?'':'These tips could not be remembered on this device; they may appear again after reopening.';$('tutorial-back').hidden=s.index===0||location;$('tutorial-next').hidden=location;$('tutorial-next').textContent=s.index+1<s.page.tips.length?'Next tip':'Got it';$('tutorial-allow').hidden=!location||!!s.status&&!s.busy;$('tutorial-retry').hidden=!location||!s.status||s.busy;$('tutorial-dismiss').textContent=location?'Continue without location':'Dismiss these tips';for(const id of ['tutorial-back','tutorial-next','tutorial-dismiss','tutorial-allow','tutorial-retry'])$(id).disabled=s.busy;$('tutorial').setAttribute('aria-busy',String(s.busy));window.requestAnimationFrame(()=>position(true));}
 const controller=createContextualTutorial({storage,requestLocation,onChange:render,onFinish:()=>close('tutorial',{force:true})});
 function open(id,options){if(controller.visit(id,options)){show('tutorial');window.requestAnimationFrame(()=>{position(true);$('tutorial-title').focus({preventScroll:true});});return true;}return false;}
 function flush(){if(controller.state().area||!canShow())return;const area=currentArea();if(!area)return;if(startupPending&&controller.state().enabled&&['journal','map','places'].includes(area)&&controller.isSeen(area)&&!controller.isSeen('location')){open('location');return;}open(area);}
 function queue(){if(timer!==null)window.clearTimeout(timer);timer=window.setTimeout(()=>{timer=null;window.requestAnimationFrame(flush);},0);}
 return {
  wire(){for(const [id,action]of [['tutorial-next',()=>controller.next()],['tutorial-back',()=>controller.back()],['tutorial-dismiss',()=>controller.dismiss()],['tutorial-allow',()=>void controller.allowLocation()],['tutorial-retry',()=>void controller.allowLocation()]])$(id).onclick=action;$('show-context-tips').onchange=e=>controller.setEnabled(e.target.checked);$('settings-tutorial').onclick=()=>{controller.resetSeen();startupPending=true;onStatus('Tutorial tips reset. They will appear as you revisit each area.');};$('settings-location').onclick=()=>open('location',{force:true});document.addEventListener('click',queue);const changes=new window.MutationObserver(queue);for(const id of ['journey-editor','journey-form','journey-create-form','batch-review','photo-geotag','export-controls'])if($(id))changes.observe($(id),{attributes:true,attributeFilter:['hidden','inert']});window.addEventListener('resize',()=>position());document.addEventListener('scroll',()=>position(),true);$('show-context-tips').checked=controller.state().enabled;},
  start(){startupPending=true;queue();},queue,flush,visit:id=>open(id),
  canClose(){if(!controller.canClose()){onStatus('Finish the system permission choice before closing this tip.');return false;}return true;},
  reset(){controller.reset();anchor=null;},
  get active(){return !!controller.state().area;}
 };
}
